  'models.wizard.private': ['Private', 'Privado', 'Privat', 'Privé', 'Privato', 'Privado', '私密'],
  'models.wizard.chooseGateway': ['Choose your gateway', 'Elige tu puerta de enlace', 'Wähle dein Gateway', 'Choisissez votre passerelle', 'Scegli il tuo gateway', 'Escolha seu gateway', '选择网关'],
  'models.wizard.freeGatewayVerbose': ['Both use the same free-router target; OpenRouter is the most direct route.', 'Ambos usan el mismo enrutador gratuito; OpenRouter es la ruta más directa.', 'Beide nutzen dasselbe kostenlose Routerziel; OpenRouter ist der direkteste Weg.', 'Les deux utilisent le même routeur gratuit ; OpenRouter est le chemin le plus direct.', 'Entrambi usano lo stesso router gratuito; OpenRouter è la via più diretta.', 'Ambos usam o mesmo roteador gratuito; o OpenRouter é o caminho mais direto.', '两者使用相同的免费路由目标；OpenRouter 最直接。'],
